import re, os

# Find functions containing BOTH a header-pointer capture (skb_header_pointer or cast)
# AND a pull inside a loop within the same function.
pull_re = re.compile(r'pskb_may_pull|pskb_pull\b|__pskb_pull_tail|skb_linearize')
loop_re = re.compile(r'\b(while|for)\s*\(')

results = []
for root, dirs, files in os.walk('net'):
    for f in files:
        if not f.endswith('.c') and not f.endswith('.h'):
            continue
        path = os.path.join(root, f)
        try:
            text = open(path, errors='replace').read()
        except Exception:
            continue
        lines = text.split('\n')
        # crude function splitting: lines starting at col 0 with '{' ended by col-0 '}'
        func_start = None
        func_name = None
        for i, ln in enumerate(lines):
            if ln.startswith('{'):
                func_start = i
                # find name from previous non-empty line(s)
                prev = lines[i-1] if i > 0 else ''
                m = re.search(r'(\w+)\s*\($', prev.strip()) or re.search(r'(\w+)\s*\(', prev)
                func_name = m.group(1) if m else '?'
            elif ln.startswith('}') and func_start is not None:
                body = lines[func_start:i+1]
                has_pull = any(pull_re.search(l) for l in body)
                if has_pull:
                    # check a pull is inside a loop: find loop header, then pull before matching loop end
                    for j, l in enumerate(body):
                        if loop_re.search(l):
                            # loop body extends until brace balance closes; crude: scan forward
                            depth = 0
                            started = False
                            k = j
                            while k < len(body):
                                depth += body[k].count('{') - body[k].count('}')
                                if '{' in body[k]:
                                    started = True
                                if started and depth <= 0:
                                    break
                                if k > j and pull_re.search(body[k]):
                                    results.append((path, func_name, func_start+1+j, func_start+1+k, body[k].strip()))
                                    break
                                k += 1
                func_start = None
for r in results[:80]:
    print(r)
print(len(results))
EOF

