python3 - <<'EOF'
import re, os

# Detect: pointer captured via skb_header_pointer / direct cast BEFORE a pull,
# then dereferenced (same identifier) AFTER the pull, in functions with loops.
pull_re = re.compile(r'\b(pskb_may_pull|pskb_pull|__pskb_pull_tail|skb_linearize)\s*\(')
cap_re  = re.compile(r'^\s*(?:const\s+)?[\w\s\*]*?(\w+)\s*=\s*(?:\(.*?\)\s*)?skb_header_pointer\s*\(')
cast_re = re.compile(r'^\s*(?:const\s+)?[\w\s\*]*?(\w+)\s*=\s*\([^)]*\*\)\s*(skb->data|skb_network_header|skb_transport_header|skb_mac_header)')

results = []
for root, dirs, files in os.walk('net'):
    for f in files:
        if not f.endswith('.c'):
            continue
        path = os.path.join(root, f)
        try:
            lines = open(path, errors='replace').read().split('\n')
        except Exception:
            continue
        func_start = None
        func_name = '?'
        for i, ln in enumerate(lines):
            if ln.startswith('{'):
                func_start = i
                prev = lines[i-1] if i > 0 else ''
                m = re.search(r'(\w+)\s*\($', prev.strip()) or re.search(r'(\w+)\s*\(', prev)
                func_name = m.group(1) if m else '?'
            elif ln.startswith('}') and func_start is not None:
                body = lines[func_start:i+1]
                pulls = [j for j,l in enumerate(body) if pull_re.search(l)]
                if pulls:
                    first_pull = min(pulls)
                    # captures before first pull
                    for j in range(first_pull):
                        m = cap_re.search(body[j]) or cast_re.search(body[j])
                        if not m: continue
                        var = m.group(1)
                        # deref after last pull?
                        last_pull = max(pulls)
                        for k in range(last_pull+1, len(body)):
                            if re.search(r'\b'+re.escape(var)+r'\s*->|\*\s*'+re.escape(var)+r'\b|'+re.escape(var)+r'\s*\[', body[k]):
                                results.append((path, func_name, func_start+1, func_start+1+j+1, var, func_start+1+k+1, body[k].strip()))
                                break
                func_start = None

for r in results:
    print(r)
print("TOTAL:", len(results))
EOF

