# Detect header pointers captured BEFORE a pull and dereferenced AFTER the pull
# (any function, any pull helper), plus loop context.
pull_re = re.compile(r'\b(pskb_may_pull|pskb_pull|__pskb_pull_tail|skb_linearize|pskb_expand_head|skb_cow|skb_cow_head|skb_unclone|skb_share_check)\s*\(')
cap_re  = re.compile(r'^\s*(?:const\s+)?[\w\s\*]*?(\w+)\s*=\s*(?:\(.*?\)\s*)?(skb_header_pointer\s*\(|\(.*?\*\)\s*(?:skb->data|skb_network_header|skb_transport_header|skb_mac_header|eth_hdr|ip_hdr|ipv6_hdr|dccp_hdr|tcp_hdr|udp_hdr|mpls_hdr))')
call_re = re.compile(r'^\s*(?:const\s+)?[\w\s\*]*?(\w+)\s*=\s*(?:\(.*?\)\s*)?(?:skb_header_pointer\s*\(|\(.*?\*\)\s*(?:skb->data|skb_network_header|skb_transport_header|skb_mac_header|eth_hdr|ip_hdr|ipv6_hdr|dccp_hdr|tcp_hdr|udp_hdr|mpls_hdr))')

results = []
for root, dirs, files in os.walk('net'):
    for f in files:
        if not f.endswith('.c'):
