        except Exception:
            continue
        lines = text.split('\n')
        # split into functions
        func_start = None; func_name = '?'
        for i, ln in enumerate(lines):
            if ln.startswith('{'):
                func_start = i
                prev = lines[i-1] if i > 0 else ''
                m = re.search(r'(\w+)\s*\($', prev.strip()) or re.search(r'(\w+)\s*\(', prev)
                func_name = m.group(1) if m else '?'
            elif ln.startswith('}') and func_start is not None:
                body = lines[func_start:i+1]
                pulls = [j for j,l in enumerate(body) if pull_re.search(l)]
