cap_re = re.compile(r'^\s*(?:const\s+)?[\w\s\*]*?(\w+)\s*=\s*(?:\(.*?\)\s*)?((?:skb_header_pointer|eth_hdr|ip_hdr|ipv6_hdr|dccp_hdr|tcp_hdr|udp_hdr|sctp_hdr|mpls_hdr|icmp6?_hdr)\s*\(|\(.*?\*\)\s*\w)')

